import{_ as n,l as o,o as e,c as i,v as t,p as s,x as l,d,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"Kyle 多期与连续时间","description":"","frontmatter":{"title":"Kyle 多期与连续时间","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/kyle-multiperiod.md","filePath":"quant/kyle-multiperiod.md","lastUpdated":1789023840000}'),u={name:"quant/kyle-multiperiod.md"};function h(_,a,c,E,f,A){const r=o("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="kyle-多期与连续时间" tabindex="-1">Kyle 多期与连续时间 <a class="header-anchor" href="#kyle-多期与连续时间" aria-label="Permalink to &quot;Kyle 多期与连续时间&quot;">​</a></h1><div class="epigraph"><p>单次出清把信息一次写进价格；多期拍卖让知情者把同一条私有信息拆开，在一段噪声流里匀速释放。深度不再是一个数字，而是剩余不确定与剩余噪声时间的比。</p><footer>—— Kyle, Continuous Auctions and Insider Trading, Econometrica, 1985</footer></div><p><a href="/quant/bond-trend">债券趋势</a>把信号写在过去超额的符号上，价格被当成已经形成的输入。主干里<a href="/quant/kyle-model">单期 Kyle</a>已经给出一次批量出清的线性均衡，<a href="/quant/glosten-milgrom">Glosten-Milgrom</a>给出单位方向上的序贯学习，<a href="/quant/lob-structure">限价簿</a>与<a href="/quant/order-types">订单类型</a>给出电子盘的状态机。本课不重推单期 \\(\\lambda=\\sigma_V/(2\\sigma_u)\\)。缺口是：同一知情者若可以交易多次，他会不会第一拍就把信息砸完？连续拍卖极限里，深度与揭示路径如何随时间走。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单期模型里知情者只有一次行动。多期之后，今天的成交会改变明天做市商的信念，因而改变明天的深度。若他把全部优势压进第一拍，价格立刻贴近价值，后面的噪声掩护变得无用；若他永远不交易，租金留在手里却变现为零。问题是求出一条跨期计划：每一拍下多少，使得在做市商理性更新的约束下，剩余信息被平滑地写成价格。</p><p>连续时间把拍数送到无穷。噪声需求变成布朗型随机流，知情者选择交易速率过程。此时「一次出清揭示一半」不再是可搬运的数字：揭示是一条路径，深度是时变的。本课要回答的是路径的定性结构，而不是再给一个与单期同名的 \\(\\lambda\\) 闭式。</p><h3 id="为什么不能把单期公式按日历重贴" tabindex="-1">为什么不能把单期公式按日历重贴 <a class="header-anchor" href="#为什么不能把单期公式按日历重贴" aria-label="Permalink to &quot;为什么不能把单期公式按日历重贴&quot;">​</a></h3><p>把交易日切成 \\(N\\) 段、每段套一次单期 \\(\\lambda\\)，等于假定各段独立、知情者每段重新抽一次价值。多期 Kyle 的知情者始终拿着<strong>同一条</strong>未公开信息，各段的噪声才是新的。信念是共同的状态变量，不能切片重置。经验回归里按五分钟窗估冲击，测的是局部深度，不是这篇均衡对象。</p><p><span class="marginnote">Kyle（1989）另开一条：不完全竞争的知情者提交需求函数，而不是一个数量。那是限额供给曲线，不是本课的多期数量策略。两篇不要混成「Kyle 模型」一个词。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>离散多期：共 \\(N\\) 次拍卖。价值 \\(V\\) 在开始时被知情者观测，期末公开。第 \\(n\\) 拍噪声 \\(u_n\\) 独立，做市商看见累计净流 \\(y_n=x_n+u_n\\)，设定 \\(p_n=E[V\\mid y_1,\\ldots,y_n]\\)。知情者选 \\(x_n\\) 最大化剩余各拍利润之和。线性马尔可夫均衡里，\\(x_n\\) 对当时的定价误差 \\(V-p_{n-1}\\) 成正比，比例随剩余拍数与剩余噪声规模调整：剩余时间短、剩余噪声少，交易更急，冲击更大。</p><p>连续拍卖把拍间隔送到零。累计噪声是布朗运动，价格是对 \\(V\\) 的滤波。均衡的标志性结论是：知情者选择的交易使价格过程成为鞅，并且在终点几乎完全揭示 \\(V\\)；中途的即时深度与<strong>当时剩余的价值方差</strong>成正比、与<strong>当时剩余可用来掩护的噪声</strong>成反比。单期公式是这条关系在 \\(N=1\\) 时的切片，不是全日常数。</p><h3 id="与序贯单位模型的分工" tabindex="-1">与序贯单位模型的分工 <a class="header-anchor" href="#与序贯单位模型的分工" aria-label="Permalink to &quot;与序贯单位模型的分工&quot;">​</a></h3><p>Glosten-Milgrom 每期只来一笔单位方向，知情者不选量。多期 Kyle 的观测是带符号数量，策略是速率。两者都随时间学习，但学习的充分统计量不同：一个是方向计数，一个是累计净流。不要用 PIN 的日度买卖笔数去「验证」连续 Kyle 的揭示路径。</p>',14)),(e(),s(m,null,{default:l(()=>[p(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20LR%0A%20%20V0%5B%22%E5%90%8C%E4%B8%80%E6%9D%A1%E7%A7%81%E6%9C%89%20V%22%5D%20--%3E%20Xn%5B%22%E5%90%84%E6%8B%8D%E9%80%89%E6%8B%A9%20xn%22%5D%0A%20%20Un%5B%22%E6%96%B0%E7%9A%84%E5%99%AA%E5%A3%B0%20un%22%5D%20--%3E%20Yn%5B%22yn%20%3D%20xn%20%2B%20un%22%5D%0A%20%20Xn%20--%3E%20Yn%0A%20%20Yn%20--%3E%20Pn%5B%22pn%20%3D%20E%5BV%20%7C%20%E5%8E%86%E5%8F%B2%E6%B5%81%5D%22%5D%0A%20%20Pn%20--%3E%20Rem%5B%22%E5%89%A9%E4%BD%99%E6%96%B9%E5%B7%AE%22%5D%0A%20%20Rem%20-.-%3E%7C%22%E5%86%B3%E5%AE%9A%E4%B8%8B%E4%B8%80%E6%8B%8D%E5%BC%BA%E5%BA%A6%22%7C%20Xn%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>跨期隐蔽的代价是延迟变现。每一拍多交易一单位，当前利润增加，但价格多走一截，后面所有拍的 \\(V-p\\) 变薄。最优是把边际当前租与边际未来深度损耗抵平。噪声若在某段突然变少（开盘稀、公告后流动性撤退），同一信息优势对应的最优速率下降、冲击上升——这是时变深度，不是「lambda 估坏了」。</p><p>连续极限禁止「第一秒砸完」。若知情者在任意正长度区间内把流量奇异化，做市商立刻读出 \\(V\\)，后续深度崩溃，该策略被自己摧毁。平滑释放既是数学正则，也是有持久信息优势时拆单的策略动机；它与 Harris 讨论的大单切片在现象上相接，模型里的动机是被推断，不是外生冲击函数。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>单一知情者、外生噪声、可竞争到条件期望定价，三条都硬。多个知情者会互相抢揭示，通常加快价格收敛、改变深度路径。噪声若其实有弹性（Admati–Pfleiderer 式的择时流动性交易者），掩护变成内生，下一课才碰到策略噪声；本课仍把 \\(u\\) 当给定。真实市场有买卖价差与<a href="/quant/lob-structure">限价簿</a>几何，冲击不是单一线性函数。</p><p>连续拍卖的「时间」是交易时间，不是日历。隔夜、停牌、集合竞价要把滤波切开。把单期一半揭示公式画在横轴「一天」上，是误用。</p><p><span class="marginnote">经验 \\(\\Delta p=\\lambda y\\) 的窗内斜率可以随时段变，这与理论时变深度同方向，但窗口、哪些单计入、是否去公告，已经是<a href="/quant/kyle-lambda">回归 lambda</a> 的对象。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多期 Kyle 的知情者拿着同一条信息在一串拍卖里交易；深度随剩余不确定与剩余噪声变化，不能把单期 \\(\\lambda\\) 按日历重贴。</li><li>连续拍卖要求平滑释放：奇异流量会自我揭示，线性深度难以维持。</li><li>价格对累计流的滤波是鞅，终点揭示 \\(V\\)；中途深度是路径，不是常数。</li><li>与 Glosten-Milgrom 同属学习，观测是数量速率而不是单位方向。</li><li>1989 年的需求函数竞争是另一篇，不在本课。</li><li>出处：Kyle, <em>Econometrica</em>, 1985（多期与连续拍卖两节）；语境见 O&#39;Hara, <em>Market Microstructure Theory</em>。</li></ul>',9))])}const y=n(u,[["render",h]]);export{b as __pageData,y as default};
